/**
 * A reminder's words by step, after the first name, when the team keeps no quick reply for it: the prototype's
 * `NUDGE_DEFAULT`, its three semicolons made two sentences for the plain-words rules.
 */
const NUDGE_LINES: Readonly<Record<string, (link: string | null) => string>> = {
  portal: (link) => `did the invite come through?${link ? ` Your portal is at ${link}.` : ''}`,
  ask: () => 'checking on the number. Still good for the day you gave us?',
  msa: () => 'the agreement is in your portal to sign.',
  sow: () => 'the statement of work is in your portal to sign.',
  closeout: () => 'checking on the final waiver. It is the last paper before the last check.',
  yes: () => 'any word on our bid? Happy to walk through it.',
  contract: () => 'the contract is in your portal to sign.',
  co: () => 'the change order is in your portal to sign or decline.',
  payapp: () => 'checking on the pay application. Pay by is the day on it.',
  questions: () => 'checking on our question. Questions close soon.',
  submittals: () => 'checking on the submittal we sent you.',
  certify: () => 'checking on the pay application we sent for your certificate.',
  // The residential steps that wait on the customer (punch list #140 PR 4): the thread's Nudge reads these too.
  approved: () => 'any word on the estimate? Happy to answer any questions.',
  paid: () => 'checking on the bill. Need the pay page sent again?',
  // Customer reviews (v2.5943, punch list #185): the ask the morning after Paid. {job} and {rate} are filled on the way out:
  // the job by the run and the box, the link minted then (`_shared/ratingMint.ts` on the edge, `ratingLinkIo.ts` in the box).
  review: () => 'thank you for paying for {job}. Would you tell us how we did? It takes one tap: {rate}',
}

/** The steps with words of their own. */
export const NUDGE_LINE_STEPS: readonly string[] = Object.keys(NUDGE_LINES)

/** What the line reads of a step: its id, its name and its papers, as a `FlowStep` has them or the box's `FlowNow` (punch list #140 PR 4). */
export type NudgeLineStep = Pick<FlowStep, 'id' | 'name'> & { papers: readonly PaperId[] }

/** A paper of theirs as the message names it to them: 'your W-9'. */
const yours = (paper: PaperId): string => (FLOW_PAPERS[paper]?.name ?? paper).replace(/^their /, 'your ')

/**
 * The reminder's own line for a step: the team's quick reply for it, with their portal link when the step waits on a
 * paper of theirs; else the step's own words; else a check on that paper; else a check-in on the step. The thread's
 * Nudge reads it too (`messages/nudgeDraft.ts`, punch list #140 PR 4), so the box and the morning say the same words.
 */
export function nudgeLine(person: { first: string; reading: Pick<PersonFlow['reading'], 'kind'> }, def: NudgeLineStep, quickReplies: readonly QuickReply[] = [], link: string | null = null): string {
  const paper = def.papers.find((p) => !factForPaper(p)?.ours) ?? null
  const upload = paper && link ? ` You can upload it here: ${link}` : ''
  const team = stepLine(quickReplies, flowContactKind(person.reading.kind), def.id, '')
  if (team) return upload && link && !team.text.includes(link) && !team.text.includes('{link}') ? `${team.text}\n${upload.trim()}` : team.text
  const own = NUDGE_LINES[def.id]
  if (own) return `${person.first}, ${own(link)}`
  if (paper) return `${person.first}, checking on ${yours(paper)}.${upload}`
  return `${person.first}, checking in on ${def.name.toLowerCase()}. Anything you need from us?`
}

// ---------- the run ----------

/** One of ours or the app sent this step's reminder inside its days: at least the same day, so a second run sends none. */
export function sentLately(sent: readonly NudgeSent[], contactId: string, step: Pick<NudgeStep, 'stepId' | 'jobId'>, days: number, now: Date): boolean {
  const within = Math.max(1, days)
  return sent.some((s) => s.contactId === contactId && s.stepId === step.stepId && (s.jobId ?? null) === step.jobId && daysSince(s.at, now) < within)
}

/** Whether a text for this step and job already waits on Today's sends. */
export function offeredAlready(offered: readonly NudgeOffered[] | undefined, contactId: string, step: Pick<NudgeStep, 'stepId' | 'jobId'>): boolean {
  return (offered ?? []).some((o) => o.contactId === contactId && o.stepId === step.stepId && (o.jobId ?? null) === step.jobId)
}

/**
 * The morning's texts: of every Follow up row, each due step whose reminder the app sends (`nudge.send` is `app`) and
 * whose step is switched on, unless the person is snoozed on Follow up, one of ours or the app sent it inside its days,
 * a text for it already waits on Today's sends, or their number sent STOP or there is none. One text a person a
 * morning, their worst such step; another waits for the next run. A step set to *offers* (v2.5595) takes the same
 * road, but its text is prepared for the office to press instead of sent, and a number that is missing or sent STOP
 * holds the prepared text with why instead of keeping it back.
 */
export function planNudgeRun(input: NudgeRunInput): NudgeRun {
  const texts: NudgeText[] = []
  const offers: NudgeOffer[] = []
  const notSent: NudgeKept[] = []
  const today = todayYmdInAppTz(input.now)
  for (const row of nudgeRows(input.people, input.now, input.options)) {
    const person = input.people.find((p) => p.id === row.contactId)
    if (!person) continue
    for (const step of row.steps) {
      const def = stepById(person.flow, step.stepId)
      const n = def?.nudge
      if (!def || !n || !step.due || n.send !== 'app') continue
      const snoozed = stampDay(input.snoozed?.[person.id])
      const keep = (why: NudgeNotSent, left: readonly string[] = []) =>
        notSent.push({ contactId: person.id, stepId: step.stepId, jobId: step.jobId, why, words: notSentWords(why, snoozed, left) })
      const number = input.numbers[person.id]
      const emailOnly = input.prefers?.[person.id] === 'email'
      const mode = appSendMode(input.appSends, person.reading.kind, step.stepId)
      const link = input.links?.[person.id] ?? null
      // The blanks the run can fill itself: their first name and the job's name (v2.5943), and their page's link (v2.6079).
      // {rate} waits for the edge's mint. Any other blank is the box's to fill at a press, so the text waits (punch list #124).
      const filled = fillLine(nudgeLine(person, def, input.quickReplies, link), { first: person.first, job: step.jobId ? (person.jobs?.[step.jobId] ?? null) : null, link })
      const left = filled.left.filter((k) => k !== 'rate')
      const text = (event: string): NudgeText => ({
        contactId: person.id,
        stepId: step.stepId,
        jobId: step.jobId,
        body: filled.text,
        record: { contactId: person.id, stepId: step.stepId, jobId: step.jobId, at: input.now.toISOString(), by: 'app', how: n.how },
        event,
      })
      const oneAlready = texts.some((t) => t.contactId === person.id) || offers.some((t) => t.contactId === person.id)
      if (mode === 'off') keep('off')
      else if (n.how !== 'text') keep('not a text')
      else if (snoozed && today < snoozed) keep('snoozed')
      else if (sentLately(input.sent, person.id, step, n.days, input.now)) keep('sent lately')
      else if (offeredAlready(input.offered, person.id, step)) keep('offered')
      else if (oneAlready) keep('one a morning')
      else if (mode === 'offer')
        offers.push({
          ...text(`The app prepared the ${def.name} reminder for Today’s sends.`),
          held: !number?.number ? OFFER_HELD['no number'] : number.optedOut ? OFFER_HELD['opted out'] : emailOnly ? OFFER_HELD['prefers email'] : left.length ? offerHeldBlanks(left) : null,
        })
      else if (!number?.number) keep('no number')
      else if (number.optedOut) keep('opted out')
      else if (emailOnly) keep('prefers email')
      else if (left.length) keep('blanks left', left)
      else texts.push(text(`The app sent the ${def.name} reminder by text.`))
    }
  }
  return { texts, offers, notSent }
}
